public class Main {
    public static int[] addPoly(int[] a, int[] b) {
        int len = Math.max(a.length, b.length);
        int[] result = new int[len];
        for (int i = 0; i < len; i++) {
            int ca = i < a.length ? a[i] : 0;
            int cb = i < b.length ? b[i] : 0;
            result[i] = ca + cb;
        }
        return result;
    }

    public static void main(String[] args) {
        // A(x) = 3x^2 + 2x + 1  → [1, 2, 3] (인덱스=차수)
        int[] a = {1, 2, 3};
        // B(x) = x^2 + 4        → [4, 0, 1]
        int[] b = {4, 0, 1};

        int[] c = addPoly(a, b); // 4x^2 + 2x + 5
        for (int i = c.length - 1; i >= 0; i--)
            if (c[i] != 0)
                System.out.printf("%dx^%d ", c[i], i);
        // 4x^2 2x^1 5x^0
    }
}
