#include <iostream>

#include <vector>

#include <algorithm>

using namespace std;

vector<int> addPoly(vector<int>& a, vector<int>& b) {

    int len = max(a.size(), b.size());

    vector<int> result(len, 0);

    for (int i = 0; i < len; i++) {

        int ca = i < (int)a.size() ? a[i] : 0;

        int cb = i < (int)b.size() ? b[i] : 0;

        result[i] = ca + cb;

    }

    return result;

}

int main() {

    // A(x) = 3x^2 + 2x + 1  → {1, 2, 3}

    vector<int> a = {1, 2, 3};

    // B(x) = x^2 + 4        → {4, 0, 1}

    vector<int> b = {4, 0, 1};

    vector<int> c = addPoly(a, b); // 4x^2 + 2x + 5

    for (int i = c.size() - 1; i >= 0; i--)

        if (c[i] != 0)

            cout << c[i] << "x^" << i << " ";

    // 4x^2 2x^1 5x^0

    return 0;

}

